import{_ as r,l as o,o as e,c as l,v as n,p as s,x as t,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"GNN 资产定价","description":"","frontmatter":{"title":"GNN 资产定价","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gnn-asset-pricing.md","filePath":"quant/gnn-asset-pricing.md","lastUpdated":1789023840000}'),E={name:"quant/gnn-asset-pricing.md"};function N(c,a,m,u,_,g){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=n('<h1 id="gnn-资产定价" tabindex="-1">GNN 资产定价 <a class="header-anchor" href="#gnn-资产定价" aria-label="Permalink to &quot;GNN 资产定价&quot;">​</a></h1><div class="epigraph"><p>客户与供应商的真实经济联系，使一家公司的股票收益可以预测其贸易伙伴随后的收益；图神经网络把「沿边传递」写成可学习的消息，但不能替代边必须在信号日可获得这一条。</p><footer>—— 经济联系见 Cohen and Frazzini, Journal of Finance, 2008；消息传递的网络原语见 Kipf and Welling, ICLR 2017</footer></div><p>截面模型通常把股票当成条件独立的样本，最多用行业哑变量吸收共动。生产网络文献表明，冲击沿客户–供应商边传播：Cohen 与 Frazzini（2008）发现客户收益预测供应商随后收益；Menzly 与 Ozbas（2010）用投入产出表得到更宽的跨行业可预测性；Herskovic（2018）把网络集中度写成风险因子。图神经网络（GNN）用邻居聚合把同一张图送进可训练的层，Kipf 与 Welling 的图卷积、Veličković 等人的图注意力是常用内核。资产定价要问的不是能否在会议上把预测误差再压一点，而是：<strong>消息传递是否只使用时点图与滞后特征，以及传递的是风险、有限注意，还是泄漏。</strong> 边的经济学见<a href="/quant/supply-chain-alt">供应链与货运</a>与<a href="/quant/supply-chain-graph-factor">供应链网络因子</a>；预测协议见 <a href="/quant/gkx-nn3">GKX</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>表格模型的设计矩阵是 \\(N\\times p\\)，行之间独立。图模型多了一个邻接 \\(A_t\\)（或边权 \\(W_t\\)）：节点 \\(i\\) 的表示依赖 \\(\\{j: (j,i)\\in E_t\\}\\) 的表示。这一依赖是经济上的优点（客户信息进入供应商），也是计量上的陷阱：若 \\(A_t\\) 用了期末才披露的年报大客户、或用了同期收益来定义「相似公司」，GNN 的增益来自<a href="/quant/look-ahead-bias">前视</a>。许多计算机会议上的股票 GNN 用未来窗口的相关或用全样本图，那不是资产定价复制。</p><p>第二句话是识别。消息传递可以逼近 Cohen–Frazzini 的滞后客户收益，也可以逼近行业动量的平滑版。若不做「去掉同行业边」「只用新披露客户」这类对照，GNN 相对 MLP 的增量 \\(R^2\\) 无法对应到哪一种边。Herskovic 的网络因子关心系统性拓扑风险，不是单边滞后；把两种回归的左边混用，会把风险溢价写成 alpha。</p><h3 id="消息传递不是无条件的信息共享" tabindex="-1">消息传递不是无条件的信息共享 <a class="header-anchor" href="#消息传递不是无条件的信息共享" aria-label="Permalink to &quot;消息传递不是无条件的信息共享&quot;">​</a></h3><p>一层图卷积大致是 \\(\\tilde x_i=\\sigma\\bigl(\\sum_j \\tilde A_{ij} W x_j\\bigr)\\)。堆多层等于把 \\(k\\) 步邻居的特征混进来。金融图往往稀疏且有向（客户 → 供应商），还有极高中心度的节点（大型零售或平台）。过深的层会把全市场平均灌进每一个节点，GNN 退化成带平滑的市场因子，NN3 式的表格模型已经能做。有用的深度通常很浅：一到两阶邻居，对应 Cohen–Frazzini 的直接贸易伙伴，而不是六度分隔。</p><p><span class="marginnote">用收益相关性当边，图会随估计窗口里的共同因子而变；压力期相关上升，图变密，模型在最需要稳健时最不稳。经济边（披露的客户、IO 表）慢，但可审计。相关图必须滞后到 \\(t-1\\) 且做行业中性，否则就是在平滑同期收益。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>图。</strong> 在每个再平衡日 \\(t\\)，只用当时可获得的边：年报客户关系加上法定滞后期，或滞后的 IO 表。边权可用销售占比。禁止用 \\(t\\) 期收益、用测试年才出现的供应链数据商 vintage 而不做回溯。节点特征与 GKX 表对齐：滞后、截面 rank。标签仍是未来收益，时间切分与 purge 与表格模型相同。</p><p><strong>模型。</strong> 基线必须包括：无图的 <a href="/quant/gkx-nn3">NN3 / 弹性网</a>、Cohen–Frazzini 式客户动量（手工图特征）、再加 GNN。GNN 赢手工特征，才说明可学习的聚合有增量；只赢无图 MLP，可能只是在重新发现客户动量。图注意力（GAT）会给邻居打分：应检查高权重边是否与销售占比一致，若总是指向最大市值节点，模型在学规模，应先做<a href="/quant/size-neutral">市值中性</a>。</p><p><strong>评价。</strong> 样本外 \\(R^2\\)、IC、分位组合，外加：去掉同行业边后的增量、发表后或产品化后的衰减（与<a href="/quant/index-enhancement-decay">指增衰减</a>同一逻辑）、以及边稀疏年份的稳定性。Avramov–Cheng–Metzker 的可交易约束同样适用：小供应商往往正是图上信息多、流动性差的节点。</p><h3 id="泄漏的三种典型写法" tabindex="-1">泄漏的三种典型写法 <a class="header-anchor" href="#泄漏的三种典型写法" aria-label="Permalink to &quot;泄漏的三种典型写法&quot;">​</a></h3><p>其一，全样本构建一张静态图，再用滚动收益训练——拓扑含未来并购与披露。其二，无向化有向贸易边，把供应商信息立刻送回客户，识别从「客户领先」变成互相平滑。其三，在图上做半监督标签传播时混入了测试节点的标签。这三种都会让 GNN 看起来碾压 GKX。修复是工程而不是新架构：图的 vintage、方向、以及节点集合必须进入信息集 \\(\\mathcal{F}_t\\)。</p>',15)),(e(),s(d,null,{default:t(()=>[p(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDGE%5B%22%E6%97%B6%E7%82%B9%E5%8F%AF%E8%8E%B7%E5%BE%97%E7%9A%84%E7%BB%8F%E6%B5%8E%E8%BE%B9%22%5D%20--%3E%20G%5B%22%E5%9B%BE%20A_t%22%5D%0A%20%20X%5B%22%E6%BB%9E%E5%90%8E%E8%8A%82%E7%82%B9%E7%89%B9%E5%BE%81%22%5D%20--%3E%20GNN%5B%22%E6%B5%85%E5%B1%82%E6%B6%88%E6%81%AF%E4%BC%A0%E9%80%92%22%5D%0A%20%20G%20--%3E%20GNN%0A%20%20GNN%20--%3E%20Y%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E6%94%B6%E7%9B%8A%E9%A2%84%E6%B5%8B%22%5D%0A%20%20CF%5B%22Cohen-Frazzini%20%E6%89%8B%E5%B7%A5%E7%89%B9%E5%BE%81%22%5D%20--%3E%20CMP%5B%22%E5%AF%B9%E7%85%A7%E5%A2%9E%E9%87%8F%22%5D%0A%20%20Y%20--%3E%20CMP%0A%20%20MLP%5B%22%E6%97%A0%E5%9B%BE%20NN3%22%5D%20--%3E%20CMP%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有限注意：分析师按行业而不是按客户名单覆盖，客户盈余传到供应商需要时间，GNN 的第一层可以学习这个滞后核。风险：中心节点的特质冲击不抵消（Acemoglu 等），消息传递把系统性网络暴露写进节点嵌入，这时嵌入应进入协方差与风险预算，而不是只进多空排序。误定价：若市场已把边写进 ETF 与风险模型，滞后缩短，GNN 的增量应下降——这是可证伪的。</p><p>与<a href="/quant/autoencoder-factor-model">条件自动编码器</a>的关系：自动编码器用表格特征生成 \\(\\beta\\)，GNN 用邻居特征生成 \\(\\beta\\)。可以把邻居聚合当作 \\(\\beta(z_i,\\{z_j\\})\\) 的一部分，再抽潜因子；那是图版的条件因子模型。若只做节点级预测而不抽 \\(f_t\\)，仍停留在 GKX 的预测问题。两种目标不要混报成一个「GNN 定价」数字。</p><p><span class="marginnote">中心节点在反向传播里梯度大，模型容易变成「跟着几家核心公司走」。应报告去掉最大度节点后的样本外表现；若增益消失，学到的是系统重要性，不是沿边的可交易滞后。</span></p><h3 id="中国披露与边的生存偏差" tabindex="-1">中国披露与边的生存偏差 <a class="header-anchor" href="#中国披露与边的生存偏差" aria-label="Permalink to &quot;中国披露与边的生存偏差&quot;">​</a></h3><p>A 股大客户附注有截断、重组与壳，边的生存偏差大于 Compustat 客户文件。用当年年报解释当年收益是前视；用上市后才出现的完整供应链回填历史，是另一类前视。GNN 不能修复边的质量，只会放大错误边。宁可稀疏且滞后，不要密且脏。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把会议论文的预测准确率直接写成资产定价发现。不要用日频相关图去「增强」月频 GKX 特征而不做泄漏审计。不要堆很深的 GNN。可做的是：锁 vintage、浅层、强制对照手工图因子、把中心度暴露交给风险模型。图注意力的权重应可导出、可按年稳定，否则不能进投资过程。</p><p><span class="marginnote">出处：Cohen and Frazzini, <em>JF</em>, 2008；Menzly and Ozbas, <em>JF</em>, 2010；Herskovic, <em>JF</em>, 2018；Acemoglu, Carvalho, Ozdaglar and Tahbaz-Salehi, <em>Econometrica</em>, 2012；Kipf and Welling, ICLR 2017；Veličković et al., ICLR 2018；Gu, Kelly and Xiu, <em>RFS</em>, 2020。计算机文献提供层，不提供信息集。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GNN 把贸易网络上的消息传递参数化；经济识别仍建立在 Cohen–Frazzini 一类时点边上。</li><li>必须对照无图 NN3 与手工客户动量；否则增量可能只是行业平滑或规模。</li><li>图的 vintage、方向与深度是泄漏与过平滑的主要来源。</li><li>中心度更像风险，单边滞后更像有限注意；评价要能分开。</li><li>出处：Cohen–Frazzini, <em>JF</em>, 2008；Herskovic, <em>JF</em>, 2018；Kipf–Welling, 2017；Gu–Kelly–Xiu, <em>RFS</em>, 2020。</li></ul>',11))])}const f=r(E,[["render",N]]);export{A as __pageData,f as default};
